-- [종합 상징물] 기존 15개 이상 항구 상징물의 원본 RGB 확인.
local S=game:GetService('ReplicatedStorage'):WaitForChild('Shared') local P=require(S:WaitForChild('Ports')) local I=require(S:WaitForChild('PortIdentity')) local n=0
for id in P.Ports do local v=I.get(id) if v then assert(v.landmark and v.landmark.id,'LANDMARK_MISSING:'..id)
for _,color in {v.facade,v.roofTint} do assert(type(color)=='table' and #color==3,'LANDMARK_COLOR:'..id)
for _,value in color do assert(type(value)=='number' and value>=0 and value<=255,'LANDMARK_RGB:'..id) end end n+=1 end end
assert(n>=15,'LANDMARK_COUNT:'..n) return 'LANDMARKS_PASS:'..n
